style.css:
@-moz-document domain("bandlab.com") {
/* --- Main Backgrounds & Panels --- */
  body, 
  div[class*="app"], 
  div[class*="studio"],
  main {
    background-color: #e5e5e5 !important;
    color: #121212 !important;
  }

  /* Header & Navigation */
  header, 
  nav, 
  div[class*="header"], 
  div[class*="nav"] {
    background-color: #d6d6d6 !important;
    border-bottom: 1px solid #a5a5a5 !important;
  }

  /* Track Headers & Sidebar Panels */
  div[class*="track-header"], 
  div[class*="sidebar"], 
  div[class*="track-control"] {
    background-color: #d6d6d6 !important;
    border-right: 1px solid #a5a5a5 !important;
    border-bottom: 1px solid #a5a5a5 !important;
  }

  /* --- Buttons & Active States --- */
  button {
    background-color: #c8c8c8 !important;
    color: #121212 !important;
    border: 1px solid #a5a5a5 !important;
    border-radius: 2px !important;
  }

  button:hover {
    background-color: #b8b8b8 !important;
  }

  /* Highlight active buttons with Ableton Yellow */
  button[class*="active"], 
  button[class*="primary"],
  .is-active {
    background-color: #ffc800 !important;
    color: #000000 !important;
  }

  /* --- Playhead Line --- */
  div[class*="playhead"], 
  div[class*="scrubber"] {
    background-color: #ff3300 !important;
  }

  /* --- Bottom FX Panel & Editors --- */
  div[class*="bottom-panel"], 
  div[class*="piano-roll"], 
  div[class*="fx-rack"] {
    background-color: #d6d6d6 !important;
    border-top: 2px solid #a5a5a5 !important;
  }
}
